        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                for dz in (-1, 0, 1):
                    if dx == 0 and dy == 0 and dz == 0:
                        continue
                    nxt = (x + dx, y + dy, z + dz)
                    if nxt in blocked:
                        continue
                    ng = g + math.sqrt(dx * dx + dy * dy + dz * dz)
                    if ng >= best.get(nxt, float('inf')) - EPS:
                        continue
                    qdx = (nxt[0] * 1000 - qx) / 1000.0
                    qdy = (nxt[1] * 1000 - qy) / 1000.0
                    qdz = (nxt[2] * 1000 - qz) / 1000.0
                    nh = max(0.0, math.sqrt(qdx * qdx + qdy * qdy + qdz * qdz) - TETHER)
                    nf = ng + nh
                    if nf > LIMIT + EPS:
                        continue
                    best[nxt] = ng
                    heapq.heappush(heap, (nf, ng, nxt))
    return answer if answer <= LIMIT + EPS else None

def main():
    outdir = Path('/task/output')
    outdir.mkdir(exist_ok=True)
    rows = list(csv.DictReader(open('/task/input/crosslinks.csv', newline='')))
    models = sorted(Path('/task/input/models').glob('model_*.pdb'))
    status_rows = []
    restraint_rows = []
    scores = {}
    for model_path in models:
        t0 = time.time()
        atoms, coords = parse_model(model_path)
        blocked = make_blocked(atoms)
        inter_total = intra_total = inter_sat = intra_sat = 0
        for row in rows:
            a = (row['protein_a'], int(row['position_a']))
            b = (row['protein_b'], int(row['position_b']))
            is_inter = a[0] != b[0]
            present_a = bool(coords.get(a))
            present_b = bool(coords.get(b))
            if not present_a or not present_b:
                status = 'not_evaluable'
            else:
                if is_inter:
                    inter_total += 1
                else:
                    intra_total += 1
                assignments = []
                for chain_a, point_a in coords[a]:
                    for chain_b, point_b in coords[b]:
                        if a == b and chain_a == chain_b:
                            continue
                        if math.dist(point_a, point_b) / 1000.0 <= LIMIT + EPS:
                            assignments.append((point_a, point_b))
                status = 'violated'
                for point_a, point_b in assignments:
                    if surface_distance(point_a, point_b, blocked) is not None:
                        status = 'satisfied'
                        break
            if status == 'satisfied':
                if is_inter:
                    inter_sat += 1
                else:
                    intra_sat += 1
            status_rows.append((model_path.stem, row['xl_id'], status))
        total = inter_sat + intra_sat
        scores[model_path.stem] = total
        restraint_rows.append((model_path.stem, inter_sat, inter_total, intra_sat, intra_total))
        print(model_path.stem, 'inter', inter_sat, '/', inter_total, 'intra', intra_sat, '/', intra_total, 'total', total, 'elapsed', round(time.time() - t0, 2), flush=True)
    with open(outdir / 'restraints.tsv', 'w', newline='') as f:
        f.write('model\tinter_satisfied\tinter_total\tintra_satisfied\tintra_total\n')
        for row in restraint_rows:
            f.write('\t'.join(map(str, row)) + '\n')
    with open(outdir / 'link_status.tsv', 'w', newline='') as f:
        f.write('model\txl_id\tstatus\n')
        for row in status_rows:
            f.write('\t'.join(map(str, row)) + '\n')
    ranking = sorted(scores, key=lambda name: (-scores[name], name))
    with open(outdir / 'selection.json', 'w') as f:
        json.dump({'best_model': ranking[0], 'ranking': ranking}, f, indent=2)
        f.write('\n')

if __name__ == '__main__':
    main()
